        />
        {fieldErrors.name !== undefined ? (
          <p className="text-xs text-rose-600">{fieldErrors.name[0]}</p>
        ) : null}
      </div>

      <div className="space-y-1">
        <label htmlFor="description" className="text-sm font-medium">
          Description
        </label>
        <textarea
          id="description"
          name="description"
          rows={4}
          defaultValue={project.description ?? ""}
          className="w-full rounded-md border border-slate-300 px-3 py-2 text-sm"
        />
      </div>

      <div className="grid gap-4 sm:grid-cols-2">
        <div className="space-y-1">
          <label htmlFor="visibility" className="text-sm font-medium">
            Visibility
          </label>
          <select
            id="visibility"
            name="visibility"
            defaultValue={project.visibility}
            className="w-full rounded-md border border-slate-300 px-3 py-2 text-sm"
          >
            <option value="private">Private — people on the project</option>
            <option value="org">Organization — everybody here</option>
            <option value="public">Public — anybody with the link</option>
          </select>
        </div>

        <div className="space-y-1">
          <label htmlFor="status" className="text-sm font-medium">
            Status
          </label>
          <select
            id="status"
            name="status"
            defaultValue={project.status}
            className="w-full rounded-md border border-slate-300 px-3 py-2 text-sm"
          >
            <option value="active">Active</option>
            <option value="paused">Paused</option>
            <option value="completed">Completed</option>
          </select>
        </div>
      </div>

      <div className="grid gap-4 sm:grid-cols-2">
        <div className="space-y-1">
          <label htmlFor="leadId" className="text-sm font-medium">
            Lead
          </label>
          <select
            id="leadId"
            name="leadId"
            defaultValue={project.leadId ?? ""}
            className="w-full rounded-md border border-slate-300 px-3 py-2 text-sm"
          >
            <option value="">No lead</option>
            {members.map((member) => (
              <option key={member.id} value={member.userId}>
                {member.user.name}
              </option>
            ))}
          </select>
        </div>

        <div className="space-y-1">
          <label htmlFor="color" className="text-sm font-medium">
            Colour
          </label>
          <input
            id="color"
            name="color"
            type="color"
            defaultValue={project.color}
            className="h-9 w-16 rounded border border-slate-300"
          />
        </div>
      </div>

      <button
        type="submit"
        disabled={pending}
        className="rounded-md bg-indigo-600 px-4 py-2 text-sm font-medium text-white disabled:opacity-60"
      >
        {pending ? "Saving…" : "Save project"}
      </button>
    </form>
  );
}

/**
 * Membership rows. Every read is filtered by `orgId`; removal is a soft delete.
 *
 * Must call (do not reimplement): archivePatch, shouldFilterArchived
 */
import { and, count, desc, eq, isNull, like, or } from "drizzle-orm";
import { newId } from "@/lib/id";
import { archivePatch, shouldFilterArchived } from "@/lib/soft-delete";
import { getDb, members, users } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { orgPredicate } from "./base-repository";
import { compact, keysetPredicate, probeLimit, toPage } from "./_paging";
import { toMember, toUser } from "./_mappers";
import type { ListMembersInput } from "@/schemas/member";
import type { IsoTimestamp, MemberId, OrgId, Page, UserId } from "@/types/common";
import type { Member, MemberWithUser, Role } from "@/types/member";

/**
 * A removed member is archived, never deleted, and no read ever surfaces one:
 * the scope is fixed here rather than threaded through every call site.
 */
const LIVE_MEMBERS: { readonly includeArchived?: boolean } = {};

function liveMemberPredicate() {
  return shouldFilterArchived(LIVE_MEMBERS) ? isNull(members.archivedAt) : undefined;
}

export async function findMember(
  orgId: OrgId,
  userId: UserId,
): Promise<Member | null> {
  const row = getDb()
    .select()
    .from(members)
    .where(
      and(
        orgPredicate(members.orgId, orgId),
        eq(members.userId, userId),
        liveMemberPredicate(),
      ),
    )
    .get();
  return row ? toMember(row) : null;
}

export async function findMemberById(
  orgId: OrgId,
  memberId: MemberId,
): Promise<Member | null> {
  const row = getDb()
    .select()
    .from(members)
    .where(and(orgPredicate(members.orgId, orgId), eq(members.id, memberId)))
    .get();
  return row ? toMember(row) : null;
}

/** Cursor-paged member list joined with the user record the UI renders. */
export async function listMembers(
  input: ListMembersInput,
): Promise<Page<MemberWithUser>> {
  const db = getDb();
  const sort = { sortColumn: members.createdAt, idColumn: members.id };

  const filters = compact(
    orgPredicate(members.orgId, input.orgId),
    liveMemberPredicate(),
    input.role === undefined ? undefined : eq(members.role, input.role),
    input.status === undefined ? undefined : eq(members.status, input.status),
    input.query === undefined
      ? undefined
      : or(
          like(users.name, `%${input.query}%`),
          like(users.email, `%${input.query}%`),
        ),
  );

  const total = db
    .select({ value: count() })
    .from(members)
    .innerJoin(users, eq(users.id, members.userId))
    .where(and(...filters))
    .get();

  const rows = db
    .select({ member: members, user: users })
    .from(members)
    .innerJoin(users, eq(users.id, members.userId))
    .where(and(...filters, ...compact(keysetPredicate(sort, input.cursor))))
    .orderBy(desc(members.createdAt), desc(members.id))
    .limit(probeLimit(input.limit))
    .all();

  return toPage(
    rows,
    input.limit,
    total?.value ?? 0,
    (row) => ({ ...toMember(row.member), user: toUser(row.user) }),
    (row) => ({ id: row.member.id, sortValue: row.member.createdAt }),
  );
/** Project slug/key validation and the archive scope extension. */
import { describe, expect, it } from "vitest";
import {
  archiveProjectSchema,
  createProjectSchema,
  listProjectsSchema,
  projectStatusSchema,
  projectVisibilitySchema,
  updateProjectSchema,
} from "@/schemas/project";
import { RESERVED_SLUGS } from "@/lib/slug";
import { ORG_A } from "../helpers/factories";

const PROJECT = "01HZZZPPPPPPPPPPPPPPPPPPPP";

function createInput(overrides: Record<string, unknown> = {}) {
  return {
    orgId: ORG_A,
    name: "Website relaunch",
    slug: "website-relaunch",
    key: "WEB",
    ...overrides,
  };
}

describe("schemas/project", () => {
  it("applies the documented defaults", () => {
    expect(createProjectSchema.parse(createInput())).toMatchObject({
      description: null,
      visibility: "org",
      leadId: null,
      color: "#6366f1",
      targetDate: null,
    });
  });

  it("accepts the visibility and status vocabularies", () => {
    for (const visibility of ["private", "org", "public"]) {
      expect(projectVisibilitySchema.safeParse(visibility).success, visibility).toBe(true);
    }
    for (const status of ["active", "paused", "completed"]) {
      expect(projectStatusSchema.safeParse(status).success, status).toBe(true);
    }
    expect(projectVisibilitySchema.safeParse("secret").success).toBe(false);
  });

  it("shares the slug rules with @/lib/slug", () => {
    expect(createProjectSchema.safeParse(createInput({ slug: "Website" })).success).toBe(
      false,
    );
    expect(createProjectSchema.safeParse(createInput({ slug: "web--site" })).success).toBe(
      false,
    );
    expect(createProjectSchema.safeParse(createInput({ slug: "a" })).success).toBe(false);
  });

  it("refuses a reserved slug", () => {
    for (const reserved of RESERVED_SLUGS.slice(0, 5)) {
      const result = createProjectSchema.safeParse(createInput({ slug: reserved }));
      expect(result.success, reserved).toBe(false);
    }
  });

  it("requires a 2-4 character uppercase project key", () => {
    expect(createProjectSchema.safeParse(createInput({ key: "WEB" })).success).toBe(true);
    expect(createProjectSchema.safeParse(createInput({ key: "W" })).success).toBe(false);
    expect(createProjectSchema.safeParse(createInput({ key: "WEBSITE" })).success).toBe(
      false,
    );
    expect(createProjectSchema.safeParse(createInput({ key: "web" })).success).toBe(false);
    expect(createProjectSchema.safeParse(createInput({ key: "1WE" })).success).toBe(false);
    expect(createProjectSchema.safeParse(createInput({ key: "W3B" })).success).toBe(true);
  });

  it("requires a #rrggbb colour", () => {
    expect(createProjectSchema.safeParse(createInput({ color: "#abcdef" })).success).toBe(
      true,
    );
    expect(createProjectSchema.safeParse(createInput({ color: "indigo" })).success).toBe(
      false,
    );
    expect(createProjectSchema.safeParse(createInput({ color: "#abc" })).success).toBe(
      false,
    );
  });

  it("bounds the name and description", () => {
    expect(createProjectSchema.safeParse(createInput({ name: "W" })).success).toBe(false);
    expect(
      createProjectSchema.safeParse(createInput({ name: "a".repeat(81) })).success,
    ).toBe(false);
    expect(
      createProjectSchema.safeParse(createInput({ description: "a".repeat(2_001) }))
        .success,
    ).toBe(false);
  });

  it("makes update fields optional but does not allow a slug or key change", () => {
    const parsed = updateProjectSchema.parse({ orgId: ORG_A, projectId: PROJECT });
    expect(parsed).toEqual({ orgId: ORG_A, projectId: PROJECT });
    expect("slug" in parsed).toBe(false);
    expect("key" in parsed).toBe(false);
  });

  it("defaults an archive to cascading over the project's issues", () => {
    expect(archiveProjectSchema.parse({ orgId: ORG_A, projectId: PROJECT })).toEqual({
      orgId: ORG_A,
      projectId: PROJECT,
      archiveIssues: true,
    });
    expect(
      archiveProjectSchema.parse({
        orgId: ORG_A,
        projectId: PROJECT,
        archiveIssues: false,
      }).archiveIssues,
    ).toBe(false);
  });

  it("extends the list schema with pagination and archive scope", () => {
    const parsed = listProjectsSchema.parse({ orgId: ORG_A });
    expect(parsed.limit).toBe(25);
    expect(parsed.includeArchived).toBeUndefined();
    expect(
      listProjectsSchema.parse({ orgId: ORG_A, includeArchived: true }).includeArchived,
    ).toBe(true);
  });
});
